function [r] = flex_reduced_inertia(inertia, delta)
%FLEX_REDUCED_INERTIA  The reduced inertia J - delta delta^T the body's equation divides by when the mode is on.
%   inertia: real[1][3][3] (passed a plain number)
%   delta: real[1][3] (passed a plain number)
%   returns r: real[1][3][3] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    r = zeros(3, 3);
    r = inertia;
    ia = ((0):((3) - 1)).';
    ic = (0):((3) - 1);
    r((ia) + 1, (ic) + 1) = (r((ia) + 1, (ic) + 1) - (reshape(delta((ia) + 1), [], 1) .* reshape(delta((ic) + 1), 1, [])));
end
